WITH clock AS (SELECT public.olap_reporting_date() today), selected AS (SELECT d."Date" FROM (SELECT generate_series(DATE '1900-01-01',DATE '2199-12-31',interval '1 day')::date "Date") d WHERE [[{{period}} --]] d."Date" BETWEEN (SELECT today-30 FROM clock) AND (SELECT today-1 FROM clock)
), bounds AS (SELECT min("Date") starts,max("Date") ends,count(*) days,count(*)>0 AND count(*)=max("Date")-min("Date")+1 AND max("Date")<=(SELECT today FROM clock) valid FROM selected), cohort AS (SELECT p.* FROM bounds b CROSS JOIN LATERAL public.reporting_borrower_period_v1(b.starts,b.ends,[[{{population}} --]] 'All with loan history'
) p WHERE b.valid), series AS (SELECT borrower_id,CASE WHEN interest_rank<=5 THEN borrower_label ELSE 'Others' END label FROM cohort), grid AS (SELECT s.borrower_id,s.label,d."Date" FROM series s CROSS JOIN selected d CROSS JOIN bounds b WHERE b.valid)
 SELECT CASE WHEN b.days<=60 THEN g."Date" ELSE date_trunc('week',g."Date")::date END AS "Date",g.label AS "Borrower",CASE WHEN g.label<>'Others' THEN min(g.borrower_id) END AS "Borrower ID",
 CASE WHEN bool_and(a.activity_date IS NULL OR a.interest_received IS NOT NULL) THEN sum(coalesce(a.interest_received,0)) END AS "Interest ฿"
 FROM grid g CROSS JOIN bounds b LEFT JOIN public.reporting_borrower_activity_daily_v1 a ON a.borrower_id=g.borrower_id AND a.activity_date=g."Date" GROUP BY 1,2 ORDER BY 1,2
